import csv,re,collections
paths=['inputs/CRISPRGeneEffect.csv','inputs/OmicsExpressionProteinCodingGenesTPMLogp1BatchCorrected.csv']
hs=[]
for path in paths:
 with open(path,newline='') as f: hs.append(next(csv.reader(f))[1:])
for i,h in enumerate(hs):
 d=collections.defaultdict(list)
 for z in h:
  m=re.fullmatch(r'(.+) \\((\\d+)\\)',z); d[m.group(2)].append(z)
 hs[i]=d
for k,v in hs[1].items():
 if len(v)>1:
  print(k,'effect=',hs[0].get(k),'expr=',v)
